// JobDisplayName 把游戏库 characters 的 (job, grow_type) 解成中文职业名。
//
// 数据一律按当前 PVF 生成；查不到的 job 返回「职业 N」而不是空串 ——
// 界面上宁可显示一个可疑的数字，也不要显示成空白（空白会被当成「查询出错」）。
func JobDisplayName(job, growType int) string {
	def, ok := jobCatalog[job]
	if !ok {
		return fmt.Sprintf("职业 %d", job)
	}

	first := growType & 0xF
	second := (growType >> 4) & 0xF

	if second > 0 {
		if aw := def.Awakenings[first]; len(aw) >= second {
			return aw[second-1]
		}
	}
	if first > 0 && first <= len(def.GrowNames) {
		if n := cleanJobName(def.GrowNames[first-1]); n != "" {
			return n
		}
	}

	name := def.BaseName
	if name == "" {
		name = def.Token
	}
	if growType == 0 {
		if g, ok := jobBaseGender[job]; ok {
			name += "（" + g + "）"
		}
	}
	return name
}

// cleanJobName 去掉 PVF 名的反引号；占位名（// 注释、growtype_name_x、??）
// 返回空串，让调用方回退到基础职业名。
func cleanJobName(s string) string {
	t := strings.TrimSpace(strings.Trim(strings.TrimSpace(s), "`"))
	if t == "" || t == "??" || t == "？？" ||
		strings.HasPrefix(t, "//") ||
		strings.HasPrefix(strings.ToLower(t), "growtype_name_") {
		return ""
	}
	return t
}
